public sealed class CatalogLoadResult { public CatalogDto catalog; public RulesetDto rules; public string error; public bool Success { get { return catalog != null && rules != null && string.IsNullOrEmpty(error); } } }
public static class CatalogLoader {
 const string CH="45c0501dc2028c030c3d904895a88d1fecaa53591f42ac38e1937f5c39d1fc30", RH="3e0a9ef1d6b3f0fde22c5814198946ba53744973d851fcf7e2cc8035e0e4ef95";
 public const int ExpectedLevelCount=30;
 const string CatalogName="approved_levels_v4.json", RulesName="ruleset_manifest_v1.json";
 public static CatalogDto Load(out RulesetDto rules) {
  if (UseWebRequest()) throw new PlatformNotSupportedException("CatalogLoader.Load cannot read Android StreamingAssets synchronously. Use LoadRoutine.");
  var root=Path.Combine(Application.streamingAssetsPath,"HabitatShift");
  var catalogPath=Path.Combine(root,CatalogName); var rulesPath=Path.Combine(root,RulesName);
  try { return LoadFromBytes(ReadDesktop(catalogPath,"catalog"),ReadDesktop(rulesPath,"ruleset"),out rules); }
  catch(Exception e) { throw new InvalidOperationException("Catalog desktop load failed: "+e.Message,e); }
 }
 public static IEnumerator LoadRoutine(Action<CatalogLoadResult> complete) {
  var result=new CatalogLoadResult(); byte[] catalogBytes=null,rulesBytes=null;
  if (UseWebRequest()) {
   yield return ReadRequest(BuildStreamingUri(CatalogName),"catalog",bytes=>catalogBytes=bytes,error=>result.error=error);
   if (string.IsNullOrEmpty(result.error)) yield return ReadRequest(BuildStreamingUri(RulesName),"ruleset",bytes=>rulesBytes=bytes,error=>result.error=error);
  } else {
   try { var root=Path.Combine(Application.streamingAssetsPath,"HabitatShift"); catalogBytes=ReadDesktop(Path.Combine(root,CatalogName),"catalog"); rulesBytes=ReadDesktop(Path.Combine(root,RulesName),"ruleset"); }
   catch(Exception e) { result.error="Catalog desktop resource load failed: "+e.Message; }
  }
  if (string.IsNullOrEmpty(result.error)) {
   try { result.catalog=LoadFromBytes(catalogBytes,rulesBytes,out result.rules); }
   catch(Exception e) { result.error=e.Message; }
  }
  complete?.Invoke(result);
 }
 static IEnumerator ReadRequest(string uri,string resource,Action<byte[]> success,Action<string> failure) {
  using(var request=UnityWebRequest.Get(uri)) {
   yield return request.SendWebRequest();
   if (request.result!=UnityWebRequest.Result.Success) { failure("Catalog "+resource+" transport error at "+uri+": "+request.error); yield break; }
   var bytes=request.downloadHandler==null?null:request.downloadHandler.data;
   if (bytes==null||bytes.Length==0) { failure("Catalog "+resource+" payload is empty at "+uri+"."); yield break; }
   success(bytes);
  }
 }
 static byte[] ReadDesktop(string path,string resource) { if(!File.Exists(path)) throw new FileNotFoundException("Catalog "+resource+" resource is missing.",path); var bytes=File.ReadAllBytes(path); if(bytes==null||bytes.Length==0)throw new InvalidOperationException("Catalog "+resource+" payload is empty."); return bytes; }
 static bool UseWebRequest() { return Application.platform==RuntimePlatform.Android && !Application.isEditor; }
 static string BuildStreamingUri(string file) { return Application.streamingAssetsPath.TrimEnd('/','\\')+"/HabitatShift/"+file; }
 public static CatalogDto LoadFromBytes(byte[] catalogBytes,byte[] rulesBytes,out RulesetDto rules) {
  VerifyExpectedHash(catalogBytes,CH,"catalog"); VerifyExpectedHash(rulesBytes,RH,"ruleset"); return DeserializeValidatedPayloads(catalogBytes,rulesBytes,out rules);
 }
 public static CatalogDto DeserializeValidatedPayloads(byte[] catalogBytes,byte[] rulesBytes,out RulesetDto rules) {
  EnsurePayload(catalogBytes,"catalog"); EnsurePayload(rulesBytes,"ruleset");
  try {
   var raw=Regex.Replace(DecodeUtf8(catalogBytes,"catalog"),"\\[\\s*(-?\\d+(?:\\.\\d+)?)\\s*,\\s*(-?\\d+(?:\\.\\d+)?)\\s*\\]","{\"x\":$1,\"y\":$2}");
   var catalog=JsonUtility.FromJson<CatalogDto>(raw); rules=JsonUtility.FromJson<RulesetDto>(DecodeUtf8(rulesBytes,"ruleset")); Validate(catalog,rules); return catalog;
  } catch(InvalidOperationException) { throw; } catch(Exception e) { throw new InvalidOperationException("Catalog JSON parse failed: "+e.Message,e); }
 }
 public static void VerifyExpectedHash(byte[] bytes,string expected,string resource) { EnsurePayload(bytes,resource); var actual=HashBytes(bytes); if(!string.Equals(actual,expected,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Catalog "+resource+" SHA-256 mismatch. Expected "+expected+", received "+actual+"."); }
 public static string HashBytes(byte[] bytes) { EnsurePayload(bytes,"resource"); using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","").ToLowerInvariant(); }
 static void EnsurePayload(byte[] bytes,string resource) { if(bytes==null||bytes.Length==0)throw new InvalidOperationException("Catalog "+resource+" payload is empty."); }
 static string DecodeUtf8(byte[] bytes,string resource) { try { return new UTF8Encoding(false,true).GetString(bytes); } catch(Exception e) { throw new InvalidOperationException("Catalog "+resource+" UTF-8 decode failed: "+e.Message,e); } }
 public static void Validate(CatalogDto c,RulesetDto r){if(c==null||c.schema!="habitat-shift-levels-v4"||c.catalogRevision!="m8-20260929-levels-24-30"||c.rulesetVersion!="continuous-core-v2"||c.levelCount!=ExpectedLevelCount||c.levels==null||c.levels.Length!=ExpectedLevelCount)throw new InvalidOperationException("Invalid Habitat Shift catalog identity.");if(r==null||r.rulesetVersion!="continuous-core-v2"||!Mathf.Approximately(r.dragSweepStep,.08f)||r.contactSolverIterations!=4)throw new InvalidOperationException("Invalid continuous ruleset.");for(int i=0;i<ExpectedLevelCount;i++){var l=c.levels[i];if(l==null||l.id!=i+1||l.habitats==null||l.targets==null||l.elevators==null)throw new InvalidOperationException("Invalid level "+(i+1));foreach(var h in l.habitats){if(h.need<1||h.shape==null||h.shape.Length==0)throw new InvalidOperationException("Invalid habitat L"+l.id);}}}
}public enum AssistKind { NestBloom,GardenShift,RootTrim } public enum PresentationKind { DragStart,BlockedContact,Collection,ElevatorRelease,HabitatComplete,AssistSuccess,Undo,Win }
[Serializable] public class HabitatRuntime { public string id,color,constraint;public Vector2 anchor;public List<Vector2Int> shape;public int remaining;public HabitatRuntime Clone(){return new HabitatRuntime{id=id,color=color,constraint=constraint,anchor=anchor,shape=new List<Vector2Int>(shape),remaining=remaining};}}
[Serializable] public class SproutRuntime {public string id,color;public Vector2 position;public SproutRuntime Clone(){return new SproutRuntime{id=id,color=color,position=position};}}
[Serializable] public class ElevatorRuntime {public string id,direction;public Vector2 entry;public List<QueueItemDto> queue;public int nextIndex;public bool mandatory;public ElevatorRuntime Clone(){return new ElevatorRuntime{id=id,direction=direction,entry=entry,queue=new List<QueueItemDto>(queue),nextIndex=nextIndex,mandatory=mandatory};}}
[Serializable] public class RuntimeState {public int levelId,moves;public bool won;public List<HabitatRuntime> habitats=new List<HabitatRuntime>();public List<SproutRuntime> sprouts=new List<SproutRuntime>();public List<ElevatorRuntime> elevators=new List<ElevatorRuntime>();public RuntimeState Clone(){return new RuntimeState{levelId=levelId,moves=moves,won=won,habitats=habitats.Select(x=>x.Clone()).ToList(),sprouts=sprouts.Select(x=>x.Clone()).ToList(),elevators=elevators.Select(x=>x.Clone()).ToList()};}}
public class PresentationEvent {public string id,subject,color;public PresentationKind kind;public Vector2 position,targetPosition;}
public class ContinuousSession { public const float CaptureThreshold=2f/3f;const float CaptureBodyWidth=.62f,CaptureBodyHeight=.70f,CaptureBodyYOffset=-.02f;readonly LevelDto l;readonly RulesetDto r;readonly Stack<RuntimeState> history=new Stack<RuntimeState>();int eventNo;public RuntimeState Committed{get;private set;}public RuntimeState Preview{get;private set;}public string DragId{get;private set;}public Vector2 GrabOffset{get;private set;}public Vector2 DesiredPointerPose{get;private set;}public Vector2 ResolvedPose{get;private set;}public Vector2 LastSafePose{get;private set;}public Vector2 ContactNormal{get;private set;}public List<PresentationEvent> Events=new List<PresentationEvent>(); public bool IsDragging { get { return Preview != null; } } public ContinuousSession(LevelDto level,RulesetDto rules,RuntimeState restore=null){l=level;r=rules;Committed=restore??Initial(level);} public static RuntimeState Initial(LevelDto l){return new RuntimeState{levelId=l.id,habitats=l.habitats.Select(h=>new HabitatRuntime{id=h.id,color=h.color,constraint=h.movementConstraint,anchor=new Vector2(h.anchor.x,h.anchor.y),shape=h.shape.Select(q=>new Vector2Int(q.x,q.y)).ToList(),remaining=h.need}).ToList(),sprouts=l.targets.Select(t=>new SproutRuntime{id=t.id,color=t.color,position=new Vector2(t.position.x,t.position.y)}).ToList(),elevators=l.elevators.Select(e=>new ElevatorRuntime{id=e.id,direction=e.direction,entry=new Vector2(e.entry.x,e.entry.y),queue=e.queue.ToList(),nextIndex=e.nextIndex,mandatory=e.mandatory}).ToList()};}
public bool BeginDrag(string id,Vector2 p){var h=Committed.habitats.FirstOrDefault(x=>x.id==id);if(h==null)return false;Preview=Committed.Clone();DragId=id;GrabOffset=p-h.anchor;DesiredPointerPose=h.anchor;ResolvedPose=h.anchor;LastSafePose=h.anchor;ContactNormal=Vector2.zero;Emit(PresentationKind.DragStart,id,h.anchor,h.color);return true;}
public void MovePointer(Vector2 p){if(Preview==null)return;var h=Preview.habitats.FirstOrDefault(x=>x.id==DragId);if(h==null)return;var desired=p-GrabOffset;if(h.constraint=="HORIZONTAL_ONLY")desired.y=ResolvedPose.y;if(h.constraint=="VERTICAL_ONLY")desired.x=ResolvedPose.x;DesiredPointerPose=desired;var d=DesiredPointerPose-ResolvedPose;int n=Mathf.Max(1,Mathf.CeilToInt(d.magnitude/r.dragSweepStep));for(int i=0;i<n;i++){if(!SweepStep(h,d/n))break;if(!Preview.habitats.Contains(h))break;}}
bool SweepStep(HabitatRuntime h,Vector2 step){var direct=ResolvedPose+step;if(Legal(Preview,h,direct)){ApplyPose(h,direct);ReleaseContact(step);return true;}if(TryStrictCorridorProjection(h,step,out var corrected)){ApplyPose(h,corrected);return true;}Vector2 xStep=new Vector2(step.x,0),yStep=new Vector2(0,step.y);var canX=xStep.sqrMagnitude>.0000001f&&AxisAllowed(h,xStep)&&Legal(Preview,h,ResolvedPose+xStep);var canY=yStep.sqrMagnitude>.0000001f&&AxisAllowed(h,yStep)&&Legal(Preview,h,ResolvedPose+yStep);if(canX||canY){var slide=canX&&(!canY||Mathf.Abs(step.x)>=Mathf.Abs(step.y))?xStep:yStep;ApplyPose(h,ResolvedPose+slide);ContactNormal=slide==xStep?new Vector2(0,-Mathf.Sign(step.y)):new Vector2(-Mathf.Sign(step.x),0);return true;}ContactNormal=new Vector2(Mathf.Abs(step.x)>=Mathf.Abs(step.y)?-Mathf.Sign(step.x):0,Mathf.Abs(step.y)>Mathf.Abs(step.x)?-Mathf.Sign(step.y):0);Emit(PresentationKind.BlockedContact,h.id,ResolvedPose,h.color);return false;}
bool AxisAllowed(HabitatRuntime h,Vector2 step){if(h.constraint=="HORIZONTAL_ONLY")return Mathf.Abs(step.y)<.000001f;if(h.constraint=="VERTICAL_ONLY")return Mathf.Abs(step.x)<.000001f;return true;}
void ApplyPose(HabitatRuntime h,Vector2 pose){h.anchor=pose;ResolvedPose=pose;LastSafePose=pose;Collect(Preview,h);}
void ReleaseContact(Vector2 step){if(ContactNormal==Vector2.zero)return;if(Vector2.Dot(step,ContactNormal)>r.contactReleaseHysteresis||Vector2.Dot(DesiredPointerPose-ResolvedPose,ContactNormal)>r.contactReleaseHysteresis)ContactNormal=Vector2.zero;}
