public bool EndDrag(bool cancel=false){if(Preview==null)return false;if(cancel){Preview=null;DragId=null;ContactNormal=Vector2.zero;return false;}var h=Preview.habitats.FirstOrDefault(x=>x.id==DragId);if(h!=null){Vector2 settled;if(!TrySettle(Preview,h,out settled)){Preview=null;DragId=null;ContactNormal=Vector2.zero;return false;}h.anchor=settled;}bool changed=Sig(Committed)!=Sig(Preview);if(changed){history.Push(Committed.Clone());Committed=Preview;Committed.moves++;Feed();Win();}Preview=null;DragId=null;ContactNormal=Vector2.zero;return changed;} public bool Undo(){if(history.Count==0)return false;Committed=history.Pop();Emit(PresentationKind.Undo,"",Vector2.zero);return true;}public void Restart(){history.Clear();Committed=Initial(l);Events.Clear();}
public bool CanUseAssist(AssistKind k,string hid,string sid,out string reason){var h=Committed.habitats.FirstOrDefault(x=>x.id==hid);var s=Committed.sprouts.FirstOrDefault(x=>x.id==sid);reason=null;if(k==AssistKind.NestBloom){if(h==null||h.remaining<=0){reason="Choose an unfinished Habitat.";return false;}if(Committed.elevators.Any(e=>e.queue.Skip(e.nextIndex).Any(q=>q.color==h.color))){reason="Matching Sproutlings are still waiting in an Elevator.";return false;}if(Committed.sprouts.Count(x=>x.color==h.color)<h.remaining){reason="Not enough matching Sproutlings are on the board.";return false;}return true;}if(k==AssistKind.GardenShift){if(h==null||s==null||h.color!=s.color||h.remaining<=0){reason="Choose a matching Sproutling and Habitat with space.";return false;}return true;}if(k==AssistKind.RootTrim){if(h==null||h.shape.Count<=1){reason="This Habitat cannot be trimmed further.";return false;}var trimTo=TrimTarget(h);var original=h.shape;h.shape=new List<Vector2Int>{Vector2Int.zero};var legal=Legal(Committed,h,trimTo);h.shape=original;if(!legal)reason="The origin cell must remain in a legal position.";return legal;}reason="Unknown assist.";return false;}
public bool UseAssist(AssistKind k,string hid,string sid,Vector2Int leaf){string reason;if(!CanUseAssist(k,hid,sid,out reason))return false;var h=Committed.habitats.FirstOrDefault(x=>x.id==hid);var s=Committed.sprouts.FirstOrDefault(x=>x.id==sid);if(k==AssistKind.NestBloom){var targets=Committed.sprouts.Where(x=>x.color==h.color).Take(h.remaining).ToArray();foreach(var target in targets)Capture(Committed,h,target);}else if(k==AssistKind.GardenShift)Capture(Committed,h,s);else if(k==AssistKind.RootTrim){h.anchor=TrimTarget(h);h.shape=new List<Vector2Int>{Vector2Int.zero};}Win();Emit(PresentationKind.AssistSuccess,hid,h==null?Vector2.zero:h.anchor,h==null?null:h.color);return true;}
void Collect(RuntimeState s,HabitatRuntime h){foreach(var x in s.sprouts.Where(x=>x.color==h.color&&h.remaining>0&&CaptureCoverage(h,x.position)>CaptureThreshold).ToArray())Capture(s,h,x);}void Capture(RuntimeState s,HabitatRuntime h,SproutRuntime x){var intake=BestIntake(h,x.position);s.sprouts.Remove(x);h.remaining--;Emit(PresentationKind.Collection,x.id,x.position,x.color,intake);if(h.remaining==0){s.habitats.Remove(h);Emit(PresentationKind.HabitatComplete,h.id,h.anchor,h.color,intake);}}public static float CaptureCoverage(HabitatRuntime h,Vector2 p){var min=new Vector2(p.x-CaptureBodyWidth*.5f,p.y+CaptureBodyYOffset-CaptureBodyHeight*.5f);var max=min+new Vector2(CaptureBodyWidth,CaptureBodyHeight);var area=CaptureBodyWidth*CaptureBodyHeight;var covered=0f;foreach(var c in h.shape){var a=h.anchor+c;var b=a+Vector2.one;covered+=Mathf.Max(0,Mathf.Min(max.x,b.x)-Mathf.Max(min.x,a.x))*Mathf.Max(0,Mathf.Min(max.y,b.y)-Mathf.Max(min.y,a.y));}return Mathf.Clamp01(covered/area);}static Vector2 BestIntake(HabitatRuntime h,Vector2 p){var min=new Vector2(p.x-CaptureBodyWidth*.5f,p.y+CaptureBodyYOffset-CaptureBodyHeight*.5f);var max=min+new Vector2(CaptureBodyWidth,CaptureBodyHeight);var best=-1f;var intake=h.anchor+new Vector2(.5f,.5f);foreach(var c in h.shape){var a=h.anchor+c;var b=a+Vector2.one;var area=Mathf.Max(0,Mathf.Min(max.x,b.x)-Mathf.Max(min.x,a.x))*Mathf.Max(0,Mathf.Min(max.y,b.y)-Mathf.Max(min.y,a.y));if(area>best){best=area;intake=a+new Vector2(.5f,.5f);}}return intake;}void Feed(){foreach(var e in Committed.elevators){if(e.nextIndex>=e.queue.Count||Committed.sprouts.Any(x=>(x.position-e.entry).sqrMagnitude<.0001f)||Committed.habitats.Any(x=>Contains(x,e.entry,0)))continue;var q=e.queue[e.nextIndex++];Committed.sprouts.Add(new SproutRuntime{id=q.id,color=q.color,position=e.entry});Emit(PresentationKind.ElevatorRelease,e.id,e.entry,q.color);}}void Win(){Committed.won=Committed.habitats.Count==0&&Committed.sprouts.Count==0&&Committed.elevators.All(x=>!x.mandatory||x.nextIndex>=x.queue.Count);if(Committed.won)Emit(PresentationKind.Win,"",Vector2.zero);}public bool TryGetSettlePreview(out Vector2 settled){settled=Vector2.zero;if(Preview==null||string.IsNullOrEmpty(DragId))return false;var habitat=Preview.habitats.FirstOrDefault(x=>x.id==DragId);return habitat!=null&&TrySettle(Preview,habitat,out settled);}
bool TrySettle(RuntimeState s,HabitatRuntime h,out Vector2 settled){var release=h.anchor;var committed=Committed.habitats.FirstOrDefault(x=>x.id==h.id);var lockedX=committed==null?Mathf.RoundToInt(release.x):Mathf.RoundToInt(committed.anchor.x);var lockedY=committed==null?Mathf.RoundToInt(release.y):Mathf.RoundToInt(committed.anchor.y);var minX=h.shape.Min(c=>c.x);var maxX=h.shape.Max(c=>c.x);var minY=h.shape.Min(c=>c.y);var maxY=h.shape.Max(c=>c.y);var startX=-minX;var endX=l.cols-1-maxX;var startY=-minY;var endY=l.rows-1-maxY;var found=false;var bestDistance=float.MaxValue;var bestManhattan=int.MaxValue;settled=Vector2.zero;for(var y=startY;y<=endY;y++)for(var x=startX;x<=endX;x++){if(h.constraint=="HORIZONTAL_ONLY"&&y!=lockedY)continue;if(h.constraint=="VERTICAL_ONLY"&&x!=lockedX)continue;var candidate=new Vector2(x,y);if(!LegalStrict(s,h,candidate))continue;var distance=(candidate-release).sqrMagnitude;var manhattan=Mathf.Abs(x-Mathf.RoundToInt(release.x))+Mathf.Abs(y-Mathf.RoundToInt(release.y));if(!found||distance<bestDistance-.000001f||(Mathf.Abs(distance-bestDistance)<=.000001f&&(manhattan<bestManhattan||(manhattan==bestManhattan&&(y<settled.y||(y==settled.y&&x<settled.x)))))){found=true;bestDistance=distance;bestManhattan=manhattan;settled=candidate;}}return found;}static Vector2 TrimTarget(HabitatRuntime h){var c=h.shape.OrderBy(q=>q.y).ThenBy(q=>q.x).First();return new Vector2(h.anchor.x+c.x,h.anchor.y+c.y);}bool Legal(RuntimeState s,HabitatRuntime h,Vector2 a){return Legal(s,h,a,r.activeDragHabitatCollisionSkin);}bool LegalStrict(RuntimeState s,HabitatRuntime h,Vector2 a){return Mathf.Approximately(a.x,Mathf.Round(a.x))&&Mathf.Approximately(a.y,Mathf.Round(a.y))&&Legal(s,h,a,0f);}bool Legal(RuntimeState s,HabitatRuntime h,Vector2 a,float habitatCollisionSkin){foreach(var c in h.shape){var p=a+c;int x0=Mathf.FloorToInt(p.x+.0001f),x1=Mathf.CeilToInt(p.x+1-.0001f),y0=Mathf.FloorToInt(p.y+.0001f),y1=Mathf.CeilToInt(p.y+1-.0001f);for(int y=y0;y<y1;y++)for(int x=x0;x<x1;x++)if(!Playable(x,y)||(l.obstacles??new IntPair[0]).Any(o=>o.x==x&&o.y==y))return false;}foreach(var o in s.habitats.Where(x=>x!=h))if(Overlap(h,a,o,o.anchor,habitatCollisionSkin))return false;foreach(var x in s.sprouts.Where(x=>x.color!=h.color))if(Dist(h,x.position,a)<r.foreignSproutlingCollisionRadius)return false;return true;}bool Playable(int x,int y){return x>=0&&y>=0&&x<l.cols&&y<l.rows&&(l.playableMask==null||l.playableMask.Length==0||l.playableMask.Any(c=>c.x==x&&c.y==y));}static bool Contains(HabitatRuntime h,Vector2 p,float pad,Vector2? a=null){var q=a??h.anchor;return h.shape.Any(c=>p.x>=q.x+c.x-pad&&p.y>=q.y+c.y-pad&&p.x<=q.x+c.x+1+pad&&p.y<=q.y+c.y+1+pad);}static float Dist(HabitatRuntime h,Vector2 p,Vector2? a=null){var q=a??h.anchor;float d=float.MaxValue;foreach(var c in h.shape){var z=new Vector2(Mathf.Clamp(p.x,q.x+c.x,q.x+c.x+1),Mathf.Clamp(p.y,q.y+c.y,q.y+c.y+1));d=Mathf.Min(d,Vector2.Distance(p,z));}return d;}static bool Overlap(HabitatRuntime a,Vector2 aa,HabitatRuntime b,Vector2 bb,float skin){foreach(var x in a.shape)foreach(var y in b.shape){var min=aa+x+Vector2.one*skin;var max=aa+x+Vector2.one*(1-skin);var omin=bb+y;var omax=bb+y+Vector2.one;if(min.x<omax.x&&max.x>omin.x&&min.y<omax.y&&max.y>omin.y)return true;}return false;}static bool Connected(List<Vector2Int> c){var seen=new HashSet<Vector2Int>{c[0]};var q=new Queue<Vector2Int>();q.Enqueue(c[0]);while(q.Count>0){var p=q.Dequeue();foreach(var n in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right})if(c.Contains(p+n)&&seen.Add(p+n))q.Enqueue(p+n);}return seen.Count==c.Count;}void Emit(PresentationKind k,string s,Vector2 p,string color=null,Vector2? target=null){Events.Add(new PresentationEvent{id=Committed.levelId+"-"+(++eventNo),kind=k,subject=s,position=p,color=color,targetPosition=target??p});}static string Sig(RuntimeState s){return string.Join("|",s.habitats.Select(h=>h.id+":"+h.anchor+":"+h.remaining+":"+h.shape.Count))+";"+string.Join("|",s.sprouts.Select(x=>x.id+":"+x.position))+";"+string.Join("|",s.elevators.Select(x=>x.id+":"+x.nextIndex));}}
